  // padded tgtSlice to exactly n + 2*maxLag, so a transform of sliceLen is
  // enough: every product that circular wraparound would corrupt involves a
  // sample that is zero, or a lag that is never looked at. Padding to
  // sliceLen + n instead — enough for the FULL linear correlation, most of
  // which is discarded — doubles every FFT in the engine for nothing.
  const m = nextPow2(sliceLen);
  const { xRe, xIm, yRe, yIm, mag2: magBuf } = scratch(m);
  // only the real arrays need clearing: both signals are real, and fft2Real
  // takes them through one transform, ignoring the imaginary arrays on entry
