      const pos = (k / half) * (wLen - 1);
      const j = pos | 0;
      const f = pos - j;
      const a = bandWeights[j];
      const b = bandWeights[j + 1 < wLen ? j + 1 : wLen - 1];
      w *= a + (b - a) * f;
