  const peak = corr[bestIdx];
  const sign = peak < 0 ? -1 : 1;

  // second peak outside exclusion zone around primary, also by magnitude
  let second = -Infinity;
  for (let j = 0; j < nLags; j++) {
    if (Math.abs(j - bestIdx) <= exclusionSamples) continue;
    const a = Math.abs(corr[j]);
    if (a > second) second = a;
  }
  const peakRatio = second > 0 ? peakAbs / second : Infinity;

